BEGIN TRANSACTION;
CREATE TABLE appeal_records (scenario_id VARCHAR(64) NOT NULL, object_id VARCHAR(160) NOT NULL, territory_id VARCHAR(80) DEFAULT NULL, parent_id VARCHAR(160) DEFAULT NULL, version INTEGER NOT NULL, data CLOB NOT NULL, PRIMARY KEY (scenario_id, object_id));
CREATE TABLE audit_event_records (scenario_id VARCHAR(64) NOT NULL, object_id VARCHAR(160) NOT NULL, territory_id VARCHAR(80) DEFAULT NULL, parent_id VARCHAR(160) DEFAULT NULL, version INTEGER NOT NULL, data CLOB NOT NULL, PRIMARY KEY (scenario_id, object_id));
CREATE TABLE audit_outbox (event_id VARCHAR(80) NOT NULL, scenario_id VARCHAR(64) NOT NULL, dispatched BOOLEAN NOT NULL, PRIMARY KEY (event_id));
CREATE TABLE causal_edge_records (scenario_id VARCHAR(64) NOT NULL, object_id VARCHAR(160) NOT NULL, territory_id VARCHAR(80) DEFAULT NULL, parent_id VARCHAR(160) DEFAULT NULL, version INTEGER NOT NULL, data CLOB NOT NULL, PRIMARY KEY (scenario_id, object_id));
CREATE TABLE causal_node_records (scenario_id VARCHAR(64) NOT NULL, object_id VARCHAR(160) NOT NULL, territory_id VARCHAR(80) DEFAULT NULL, parent_id VARCHAR(160) DEFAULT NULL, version INTEGER NOT NULL, data CLOB NOT NULL, PRIMARY KEY (scenario_id, object_id));
CREATE TABLE citizen_records (scenario_id VARCHAR(64) NOT NULL, object_id VARCHAR(160) NOT NULL, territory_id VARCHAR(80) DEFAULT NULL, parent_id VARCHAR(160) DEFAULT NULL, version INTEGER NOT NULL, data CLOB NOT NULL, PRIMARY KEY (scenario_id, object_id));
CREATE TABLE civic_accounts (username VARCHAR(80) NOT NULL, password_hash VARCHAR(255) NOT NULL, workspace_id VARCHAR(64) NOT NULL, citizen_id VARCHAR(80) NOT NULL, roles CLOB NOT NULL, enabled BOOLEAN NOT NULL, PRIMARY KEY (username));
CREATE TABLE consultation_records (scenario_id VARCHAR(64) NOT NULL, object_id VARCHAR(160) NOT NULL, territory_id VARCHAR(80) DEFAULT NULL, parent_id VARCHAR(160) DEFAULT NULL, version INTEGER NOT NULL, data CLOB NOT NULL, PRIMARY KEY (scenario_id, object_id));
CREATE TABLE doctrine_migration_versions (version VARCHAR(191) NOT NULL, executed_at DATETIME DEFAULT NULL, execution_time INTEGER DEFAULT NULL, PRIMARY KEY (version));
INSERT INTO "doctrine_migration_versions" VALUES('DoctrineMigrations\Version20261029000100','2026-10-29 05:02:33',1);
INSERT INTO "doctrine_migration_versions" VALUES('DoctrineMigrations\Version20261029111157','2026-10-29 12:12:42',1);
CREATE TABLE experiment_records (scenario_id VARCHAR(64) NOT NULL, object_id VARCHAR(160) NOT NULL, territory_id VARCHAR(80) DEFAULT NULL, parent_id VARCHAR(160) DEFAULT NULL, version INTEGER NOT NULL, data CLOB NOT NULL, PRIMARY KEY (scenario_id, object_id));
CREATE TABLE finance_records (scenario_id VARCHAR(64) NOT NULL, object_id VARCHAR(160) NOT NULL, territory_id VARCHAR(80) DEFAULT NULL, parent_id VARCHAR(160) DEFAULT NULL, version INTEGER NOT NULL, data CLOB NOT NULL, PRIMARY KEY (scenario_id, object_id));
CREATE TABLE message_receipts (event_id VARCHAR(80) NOT NULL, scenario_id VARCHAR(64) NOT NULL, checkpoint VARCHAR(64) NOT NULL, handled_at VARCHAR(30) NOT NULL, PRIMARY KEY (event_id));
CREATE TABLE moderation_records (scenario_id VARCHAR(64) NOT NULL, object_id VARCHAR(160) NOT NULL, territory_id VARCHAR(80) DEFAULT NULL, parent_id VARCHAR(160) DEFAULT NULL, version INTEGER NOT NULL, data CLOB NOT NULL, PRIMARY KEY (scenario_id, object_id));
CREATE TABLE municipalities (code VARCHAR(5) NOT NULL, name VARCHAR(80) NOT NULL, region VARCHAR(80) NOT NULL, department VARCHAR(80) NOT NULL, vintage INTEGER NOT NULL, source_url VARCHAR(255) NOT NULL, PRIMARY KEY(code));
INSERT INTO "municipalities" VALUES('75056','Paris','Île-de-France','Paris',2026,'https://www.insee.fr/fr/metadonnees/geographie/commune/75056-paris');
