CREATE TABLE observation_records (scenario_id VARCHAR(64) NOT NULL, object_id VARCHAR(160) NOT NULL, territory_id VARCHAR(80) DEFAULT NULL, parent_id VARCHAR(160) DEFAULT NULL, version INTEGER NOT NULL, data CLOB NOT NULL, PRIMARY KEY (scenario_id, object_id));
CREATE TABLE proposal_records (scenario_id VARCHAR(64) NOT NULL, object_id VARCHAR(160) NOT NULL, territory_id VARCHAR(80) DEFAULT NULL, parent_id VARCHAR(160) DEFAULT NULL, version INTEGER NOT NULL, data CLOB NOT NULL, PRIMARY KEY (scenario_id, object_id));
CREATE TABLE proposal_revision_records (scenario_id VARCHAR(64) NOT NULL, object_id VARCHAR(160) NOT NULL, territory_id VARCHAR(80) DEFAULT NULL, parent_id VARCHAR(160) DEFAULT NULL, version INTEGER NOT NULL, data CLOB NOT NULL, PRIMARY KEY (scenario_id, object_id));
CREATE TABLE rule_set_records (scenario_id VARCHAR(64) NOT NULL, object_id VARCHAR(160) NOT NULL, territory_id VARCHAR(80) DEFAULT NULL, parent_id VARCHAR(160) DEFAULT NULL, version INTEGER NOT NULL, data CLOB NOT NULL, PRIMARY KEY (scenario_id, object_id));
CREATE TABLE simulations (id VARCHAR(64) NOT NULL, revision INTEGER NOT NULL DEFAULT 0, state CLOB NOT NULL, updated_at VARCHAR(30) NOT NULL, PRIMARY KEY(id));
CREATE TABLE vote_records (scenario_id VARCHAR(64) NOT NULL, object_id VARCHAR(160) NOT NULL, territory_id VARCHAR(80) DEFAULT NULL, parent_id VARCHAR(160) DEFAULT NULL, version INTEGER NOT NULL, data CLOB NOT NULL, consultation_id VARCHAR(80) NOT NULL, citizen_id VARCHAR(80) NOT NULL, PRIMARY KEY (scenario_id, object_id));
CREATE UNIQUE INDEX unique_active_vote ON vote_records (scenario_id, consultation_id, citizen_id);
COMMIT;
